9	/**
10	 * Emits the audit trail for a successful owner create. Runs after {@link SaveOwner} has
11	 * assigned the owner's id, logging the id, customer code, registration date, membership
12	 * level and membership number to the dedicated {@code AUDIT} logger.
13	 */
14	public class AuditOwnerCreated {
15	
16	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
17	
18	    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
19	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
20	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
21	                ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
22	    }
23	}
