11	/**
12	 * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>} (see
13	 * {@link CustomerCode}): REGION derived from the postcode and HASH8 the first 8 upper-case
14	 * hex characters of SHA-256 over the normalized telephone plus last name. Runs after the
15	 * telephone has been normalized and mutates the built {@link Owner} in place. When the
16	 * computed code collides with an existing owner's code it is de-duplicated by appending
17	 * {@code -<n>} so distinct owners always receive distinct codes.
18	 */
19	public class AssignOwnerCustomerCode {
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
22	        Set<String> taken = new HashSet<>();
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (existing.getCustomerCode() != null) {
25	                taken.add(existing.getCustomerCode());
26	            }
27	        }
28	        owner.setCustomerCode(CustomerCode.deduplicate(CustomerCode.forOwner(owner), taken::contains));
29	    }
30	}
