8	/**
9	 * Caps the built owner's membership level to at most one above the highest membership level
10	 * among the existing members of its household — the owners with the same last name and
11	 * postcode (see {@link OwnerHouseholds}). With no existing household member no cap applies.
12	 *
13	 * <p>Runs after the owner is built but before it is saved, so the household reflects the owners
14	 * that existed before this create. Each member's current level is read through
15	 * {@link OwnerMapper#membershipLevel(Owner)} so the ceiling is one above their effective level.
16	 * The ceiling is stored on the built {@link Owner} (mutated in place) and later applied by the
17	 * same mapper method when the owner's level is derived for a response.
18	 */
19	public class AssignOwnerMembershipLevelCap {
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository, OwnerMapper ownerMapper) {
22	        Integer cap = null;
23	        for (Owner member : OwnerHouseholds.members(Owners.active(ownerRepository.findAll()),
24	                owner.getLastName(), owner.getPostcode())) {
25	            int ceiling = ownerMapper.membershipLevel(member) + 1;
26	            if (cap == null || ceiling > cap) {
27	                cap = ceiling;
28	            }
29	        }
30	        owner.setMembershipLevelCap(cap);
31	    }
32	}
