1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.plugin.variable.Out;
5	import org.springframework.dao.DataAccessException;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.idempotency.OwnerIdempotencyStore;
9	import org.springframework.web.bind.annotation.RequestHeader;
10	
11	/**
12	 * Entry point of {@code POST /api/owners}: enforces idempotent creates. When the request
13	 * carries an {@code Idempotency-Key} already seen (see {@link OwnerIdempotencyStore}), the
14	 * originally created owner is published and the {@code existing} branch responds with it
15	 * (200), skipping creation entirely — so a repeat is neither a duplicate (409) nor a second
16	 * insert. Otherwise the {@code proceed} branch runs the normal create pipeline.
17	 *
18	 * <p>Runs before any body binding/validation: a repeat short-circuits regardless of the body,
19	 * which is exactly the idempotency guarantee. {@link RecordOwnerIdempotency} stores the key
20	 * once the create succeeds.
21	 */
22	public class CheckOwnerIdempotency {
23	
24	    @FunctionalInterface
25	    public interface Existing {
26	        void existing();
27	    }
28	
29	    @FunctionalInterface
30	    public interface Proceed {
31	        void proceed();
32	    }
33	
34	    public void service(@RequestHeader(name = "Idempotency-Key", required = false) String idempotencyKey,
35	            OwnerIdempotencyStore store, OwnerRepository ownerRepository, Out<Owner> existingOwner,
36	            @Flow("existing") Existing existing, @Flow("proceed") Proceed proceed) {
37	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
38	            Integer ownerId = store.find(idempotencyKey);
39	            if (ownerId != null) {
40	                Owner owner = findExisting(ownerRepository, ownerId);
41	                if (owner != null) {
42	                    existingOwner.set(owner);
43	                    existing.existing();
44	                    return;
45	                }
46	            }
47	        }
48	        proceed.proceed();
49	    }
50	
51	    private static Owner findExisting(OwnerRepository ownerRepository, int ownerId) {
52	        try {
53	            return ownerRepository.findById(ownerId);
54	        } catch (DataAccessException notFound) {
55	            return null; // owner is gone; fall back to creating afresh
56	        }
57	    }
58	}
