1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.function.Predicate;
4	
5	/**
6	 * The single definition of an owner's customer code: {@code <REGION>-<HASH8>} where REGION is
7	 * the region derived from the owner's postcode and HASH8 is the first 8 upper-case hex
8	 * characters of SHA-256 over the owner's normalized telephone plus last name. Building the
9	 * code and reading its region back both live here so the format is defined in one place.
10	 */
11	public final class CustomerCode {
12	
13	    /** Number of leading hex characters of the telephone-and-name digest kept in the code. */
14	    private static final int HASH_LENGTH = 8;
15	
16	    private static final String SEPARATOR = "-";
17	
18	    private CustomerCode() {
19	    }
20	
21	    /**
22	     * The customer code for {@code owner}. The owner's telephone must already be normalized
23	     * (see the create pipeline), since it feeds the hash.
24	     *
25	     * @param owner the owner whose identity to derive
26	     * @return the {@code <REGION>-<HASH8>} customer code
27	     */
28	    public static String forOwner(Owner owner) {
29	        String region = Locality.regionForPostcode(owner.getPostcode());
30	        String hash = Sha256.upperHex(owner.getTelephone() + owner.getLastName(), HASH_LENGTH);
31	        return region + SEPARATOR + hash;
32	    }
33	
34	    /**
35	     * De-duplicates a customer code against the codes already in use. Returns {@code customerCode}
36	     * unchanged when it is not taken; otherwise appends {@code -<n>} with the smallest {@code n} of
37	     * 2 or more that yields a code not reported as taken.
38	     *
39	     * @param customerCode the base {@code <REGION>-<HASH8>} code
40	     * @param taken tells whether a candidate code is already in use
41	     * @return a code not reported as taken by {@code taken}
42	     */
43	    public static String deduplicate(String customerCode, Predicate<String> taken) {
44	        if (!taken.test(customerCode)) {
45	            return customerCode;
46	        }
47	        for (int n = 2; ; n++) {
48	            String candidate = customerCode + SEPARATOR + n;
49	            if (!taken.test(candidate)) {
50	                return candidate;
51	            }
52	        }
53	    }
54	
55	    /**
56	     * The REGION segment of a customer code.
57	     *
58	     * @param customerCode the customer code (may be {@code null})
59	     * @return the region before the first separator, or {@code null} when the code is null
60	     */
61	    public static String region(String customerCode) {
62	        if (customerCode == null) {
63	            return null;
64	        }
65	        int separator = customerCode.indexOf(SEPARATOR);
66	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
67	    }
68	}
