==== NormalizeOwnerAddress ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Reads the create-owner body once and normalizes its address via {@link OwnerAddresses} before
 * anything else, then publishes the request for later steps. Running first means the normalized
 * address is what {@link ValidateRequiredOwnerFields} tests for blankness and what the
 * household steps ({@link AssignOwnerHousehold}, {@link AssignOwnerHouseholdSize}) compare
 * and persist, so every use of the address sees the same normalized form.
 *
 * <p>The structured form wins: when {@code addressLine1} is supplied, it and the optional
 * {@code addressLine2} are each normalized and the flat {@code address} is composed from them.
 * Otherwise the flat {@code address} is normalized on its own, so pre-structured minimal owners
 * stay accepted (backward-compatible).
 */
public class NormalizeOwnerAddress {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated) {
        if (OwnerAddresses.isPresent(request.getAddressLine1())) {
            request.setAddressLine1(OwnerAddresses.normalize(request.getAddressLine1()));
            if (request.getAddressLine2() != null) {
                request.setAddressLine2(OwnerAddresses.normalize(request.getAddressLine2()));
            }
            request.setAddress(OwnerAddresses.compose(request.getAddressLine1(), request.getAddressLine2()));
        }
        else {
            request.setAddress(OwnerAddresses.normalize(request.getAddress()));
        }
        validated.set(request);
    }
}
==== ValidateRequiredOwnerFields ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;

/**
 * Rejects a create-owner request that is missing or blank in any required field, before
 * {@link BuildOwner} runs. Reads the request already published by {@link NormalizeOwnerAddress},
 * so the address it tests for blankness is the normalized form.
 *
 * <p>An address may be supplied in either form: a non-blank structured {@code addressLine1} or
 * the flat {@code address}. Only when both are blank is {@code address} reported missing, so
 * earlier minimal (flat-address) owners stay accepted.
 */
public class ValidateRequiredOwnerFields {

    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
        List<String> missing = new ArrayList<>();
        require("firstName", request.getFirstName(), missing);
        require("lastName", request.getLastName(), missing);
        if (!OwnerAddresses.isPresent(request.getAddressLine1())
                && !OwnerAddresses.isPresent(request.getAddress())) {
            missing.add("address");
        }
        require("city", request.getCity(), missing);
        require("telephone", request.getTelephone(), missing);
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
    }

    private static void require(String field, String value, List<String> missing) {
        if (value == null || value.isBlank()) {
            missing.add(field);
        }
    }
}
