package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Locality;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates an owner request's optional postcode. When absent the request is accepted
 * unchanged; when present it must be four digits and, for a city whose region has a pinned
 * postcode range, fall within that range (see {@link Locality#postcodeAllowedForCity}).
 * Otherwise a {@link InvalidPostcodeException} is thrown (400). Reads the request already
 * published by an earlier step, so it sees the same normalized city later steps persist.
 */
public class ValidateOwnerPostcode {

    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null) {
            return;
        }
        if (!FOUR_DIGITS.matcher(postcode).matches()) {
            throw new InvalidPostcodeException("Postcode must be 4 digits, but was '" + postcode + "'");
        }
        if (!Locality.postcodeAllowedForCity(request.getCity(), Integer.parseInt(postcode))) {
            throw new InvalidPostcodeException(
                    "Postcode " + postcode + " is not valid for city '" + request.getCity() + "'");
        }
    }
}
==== RejectFutureRegistrationDate ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

/**
 * Rejects a create-owner request that supplies a registration date later than the server's
 * current date, responding 400. Runs before {@link ResolveOwnerRegistrationDate} so the raw
 * supplied date is checked before any business-day roll-forward adjusts it. A request that
 * omits the date is accepted unchanged.
 */
public class RejectFutureRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied == null) {
            return;
        }
        LocalDate serverDate = LocalDate.now();
        if (supplied.isAfter(serverDate)) {
            throw new FutureRegistrationDateException(supplied, serverDate);
        }
    }
}
==== ResolveOwnerRegistrationDate ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Resolves the effective registration date for a new owner — the date supplied in the request, or
 * the server's current date when the request omitted one — and rolls a weekend onto the next
 * business day via {@link BusinessDays}. Runs before {@link RejectDailyOwnerLimit} so the daily
 * cap counts against this same business day, and publishes the date once so
 * {@link ApplyOwnerRegistrationDate} stamps the owner with exactly the value that was counted.
 */
public class ResolveOwnerRegistrationDate {

    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
        LocalDate effective = request.getRegistrationDate() != null
                ? request.getRegistrationDate() : LocalDate.now();
        registrationDate.set(BusinessDays.rollForward(effective));
    }
}
==== RejectDailyOwnerLimit ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;

/**
 * Rejects a create-owner request once {@link #DAILY_LIMIT} or more owners have already been
 * registered on the new owner's business day, responding 429. Counts against the effective
 * registration date resolved by {@link ResolveOwnerRegistrationDate} — the supplied-or-defaulted
 * date already rolled onto a business day — so the count and the new owner share one day.
 */
public class RejectDailyOwnerLimit {

    /** Maximum number of owners that may be registered in a single day. */
    static final int DAILY_LIMIT = 100;

    public void service(@Val LocalDate registrationDate, OwnerRepository ownerRepository)
            throws DailyOwnerLimitException {
        if (OwnerRegistrationDays.size(ownerRepository.findAll(), registrationDate) >= DAILY_LIMIT) {
            throw new DailyOwnerLimitException(DAILY_LIMIT);
        }
    }
}
