package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;

/**
 * Rejects a create-owner request whose (already normalized) email uses a disposable-email
 * provider's domain, responding 400. An absent email is a no-op; disposable membership is
 * decided by the shared {@link OwnerEmails} rule set.
 */
public class RejectDisposableOwnerEmail {

    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
        String email = request.getEmail();
        if (OwnerEmails.isPresent(email) && OwnerEmails.isDisposable(email)) {
            throw new DisposableEmailDomainException(OwnerEmails.domainOf(email));
        }
    }
}
==== RejectDuplicateOwnerIdentity ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.OwnerIdentity;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;

/**
 * Rejects a create whose {@link OwnerIdentity identity key} — normalized telephone, lower-cased
 * email and surname Soundex — already belongs to an existing, active owner, with a 409. Only
 * {@link Owners#active active} owners count, so a soft-deleted owner never blocks a re-create.
 *
 * <p>Runs after the request's telephone and email have been normalized and the email-domain
 * blocklist applied, so the key is computed from the same canonical values a stored owner
 * carries. A create that clears this check but merely shares a surname Soundex and postcode is
 * flagged a soft match later by {@link AssignOwnerPossibleDuplicate}, not rejected here.
 */
public class RejectDuplicateOwnerIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerException {
        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), request.getLastName());
        for (Owner existing : Owners.active(ownerRepository.findAll())) {
            if (identityKey.equals(OwnerIdentity.of(existing))) {
                throw new DuplicateOwnerException(existing.getId());
            }
        }
    }
}
==== AssignOwnerNamesakeCount ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many existing owners already share the built owner's first and last name,
 * compared case-insensitively. Runs after the owner is built but before it is saved, so the
 * count reflects the owners that existed before this create, and mutates the built
 * {@link Owner} in place.
 */
public class AssignOwnerNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = canonical(owner.getFirstName());
        String lastName = canonical(owner.getLastName());
        int namesakes = 0;
        for (Owner existing : Owners.active(ownerRepository.findAll())) {
            if (firstName.equals(canonical(existing.getFirstName()))
                    && lastName.equals(canonical(existing.getLastName()))) {
                namesakes++;
            }
        }
        owner.setNamesakeCount(namesakes);
    }

    private static String canonical(String value) {
        return value == null ? "" : value.toLowerCase(Locale.ROOT);
    }
}
