import org.springframework.samples.petclinic.model.Owner;

/**
 * Emits the audit trail for a successful owner create. Runs after {@link SaveOwner} has
 * assigned the owner's id, logging the id, customer code, registration date, membership
 * level and membership number to the dedicated {@code AUDIT} logger.
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
    }
}

