                membershipLevel, ownerMapper.membershipNumber(owner));
        OwnerCreatedEvent event = OwnerCreatedEvent.of(sequence.next(), owner, membershipLevel);
        AUDIT.info(objectMapper.writeValueAsString(event));
    }
}

